Here's your expense tracker: add an item, pick a category and set a budget to see what's left. It keeps entries only while this page is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f7f7f5;color:#222}
  h1{font-size:18px;margin:0 0 12px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px;flex:1;min-width:110px}
  button{padding:8px 14px;border:0;border-radius:6px;background:#2f7d5b;color:#fff;font-size:14px;cursor:pointer}
  button.x{background:none;color:#b33;padding:2px 8px;font-size:16px}
  .big{font-size:24px;font-weight:600}
  .muted{color:#777;font-size:13px}
  .bar{height:8px;background:#e6e6e2;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar div{height:100%;background:#2f7d5b}
  .over{color:#b33}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
</style>
</head>
<body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div id="left" class="muted"></div>
</div>

<div class="card">
  <div class="row">
    <input id="desc" type="text" placeholder="What was it for?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button type="button" id="add">Add</button>
  </div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">All entries</div>
  <div id="list"></div>
</div>

<script>
var items = [];
var money = function(n){ return "₹" + Math.round(n).toLocaleString("en-IN"); };
var $ = function(id){ return document.getElementById(id); };

function render(){
  var total = 0, byCat = {};
  items.forEach(function(it){
    total += it.amt;
    byCat[it.cat] = (byCat[it.cat] || 0) + it.amt;
  });
  $("total").textContent = money(total);

  var b = parseFloat($("budget").value);
  var left = $("left");
  if (b > 0) {
    var diff = b - total;
    left.className = "muted" + (diff < 0 ? " over" : "");
    left.textContent = diff >= 0 ? money(diff) + " left of " + money(b)
                                 : money(-diff) + " over your budget of " + money(b);
  } else {
    left.className = "muted";
    left.textContent = "Add a budget to see what's left.";
  }

  var cats = $("cats");
  cats.textContent = "";
  var names = Object.keys(byCat).sort(function(a, c){ return byCat[c] - byCat[a]; });
  if (!names.length) { cats.textContent = "Nothing yet."; cats.className = "muted"; }
  else cats.className = "";
  names.forEach(function(n){
    var w = document.createElement("div");
    var t = document.createElement("div");
    t.style.cssText = "display:flex;justify-content:space-between;font-size:14px";
    var a = document.createElement("span"); a.textContent = n;
    var c = document.createElement("span"); c.textContent = money(byCat[n]);
    t.appendChild(a); t.appendChild(c);
    var bar = document.createElement("div"); bar.className = "bar";
    var fill = document.createElement("div");
    fill.style.width = (total ? byCat[n] / total * 100 : 0) + "%";
    bar.appendChild(fill);
    w.appendChild(t); w.appendChild(bar);
    cats.appendChild(w);
  });

  var list = $("list");
  list.textContent = "";
  if (!items.length) { list.textContent = "No entries yet."; list.className = "muted"; }
  else list.className = "";
  items.slice().reverse().forEach(function(it){
    var r = document.createElement("div"); r.className = "item";
    var l = document.createElement("span");
    l.textContent = it.desc + " (" + it.cat + ")";
    var rt = document.createElement("span");
    var amt = document.createElement("span"); amt.textContent = money(it.amt);
    var x = document.createElement("button");
    x.type = "button"; x.className = "x"; x.textContent = "×";
    x.onclick = function(){ items.splice(items.indexOf(it), 1); render(); };
    rt.appendChild(amt); rt.appendChild(x);
    r.appendChild(l); r.appendChild(rt);
    list.appendChild(r);
  });
}

function addItem(){
  var amt = parseFloat($("amt").value);
  if (!(amt > 0)) return;
  items.push({ desc: $("desc").value.trim() || "Expense", amt: amt, cat: $("cat").value });
  $("desc").value = "";
  $("amt").value = "";
  $("desc").focus();
  render();
}

$("add").onclick = addItem;
$("amt").onkeydown = function(e){ if (e.key === "Enter") addItem(); };
$("budget").oninput = render;
render();
</script>
</body>
</html>
```
